def transform(grid):
    """Shift the grid contents down one row, filling the top with background."""
    if not grid:
        return []
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    return [[bg for _ in row] for row in grid[:1]] + [row[:] for row in grid[:-1]]

